@2 n="covalent_packing_fraction" d="Composition-averaged covalent-sphere volume divided by atomic volume." B=852
def feature(s):
    if not s:
        return 0.0
    props = s.get('element_properties') or {}
    total = 0.0
    weight = 0.0
    for element, fraction in (s.get('composition') or {}).items():
        if fraction is None or fraction <= 0.0:
            continue
        radius = max(0.1, (props.get(element) or {}).get('covalent_radius_A') or 1.3)
        total += fraction * radius ** 3
        weight += fraction
    volume = s.get('volume_per_atom_A3') or 0.0
    if volume <= 0.0:
        count = sum(max(0.0, x.get('occupancy', 1.0) or 0.0) for x in s.get('sites') or [])
        cell_volume = (s.get('lattice') or {}).get('volume_A3') or 0.0
        if count > 0.0 and cell_volume > 0.0:
            volume = cell_volume / count
    if volume <= 0.0 or weight <= 0.0:
        return 0.0
    return 4.1887902047863905 * total / (weight * volume)
@end
