@7 n="chemical_contact_assortativity" d="Excess homonuclear soft-contact fraction relative to composition-random mixing." B=1176
def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    n = len(sites)
    props = s.get('element_properties') or {}
