        for bond in bonds:
            if bond.get('i', -1) != i:
                continue
            j = bond.get('j', -1)
            d = bond.get('distance_A') or 0.0
            if not (0 <= j < n and 0.0 < d < 6.0):
                continue
            u = d / (1.5 * (radii[i] + radii[j]))
            w = occ[j] * max(0.0, 1.0 - u * u) ** 2
            if w <= 0.0:
                continue
            other = sites[j].get('frac_coords') or []
            image = bond.get('image') or [0, 0, 0]
            if len(other) != 3 or len(image) != 3:
                continue
            a = other[0] + image[0] - position[0]
            b = other[1] + image[1] - position[1]
            c = other[2] + image[2] - position[2]
            dx = a * matrix[0][0] + b * matrix[1][0] + c * matrix[2][0]
            dy = a * matrix[0][1] + b * matrix[1][1] + c * matrix[2][1]
            dz = a * matrix[0][2] + b * matrix[1][2] + c * matrix[2][2]
            norm2 = dx * dx + dy * dy + dz * dz
            if norm2 <= 1e-12:
                continue
            scale = w / norm2 ** 0.5
            vx += scale * dx
            vy += scale * dy
            vz += scale * dz
            weight += w
        if weight > 1e-12:
            imbalance = (vx * vx + vy * vy + vz * vz) / (weight * weight)
            total += occ[i] * min(1.0, max(0.0, imbalance))
            centers += occ[i]
    return total / max(centers, 1e-12)
@end
@15 n="adaptive_first_shell_gap" d="Mean relative gap between the outermost adaptive first-shell contact and the next contact; ratios capped at three, unresolved gaps omitted." B=1261
def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    bonds = s.get('neighbors') or []
    n = len(sites)
    occ = [max(0.0, x.get('occupancy', 1.0) or 0.0) for x in sites]
    total = 0.0
    weight = 0.0
    for i in range(n):
        if occ[i] <= 0.0:
            continue
        nearest = 0.0
        for b in bonds:
            if b.get('i', -1) != i:
                continue
            j = b.get('j', -1)
            d = b.get('distance_A') or 0.0
            if 0 <= j < n and occ[j] > 0.0 and 0.0 < d <= 6.0:
                if nearest == 0.0 or d < nearest:
                    nearest = d
        if nearest <= 0.0:
            continue
        inner = nearest
        outer = 0.0
        for b in bonds:
            if b.get('i', -1) != i:
                continue
            j = b.get('j', -1)
            d = b.get('distance_A') or 0.0
            if 0 <= j < n and occ[j] > 0.0 and 0.0 < d <= 6.0:
                if d <= 1.25 * nearest:
                    inner = max(inner, d)
                elif outer == 0.0 or d < outer:
                    outer = d
        if outer > 0.0:
            total += occ[i] * (min(3.0, outer / inner) - 1.0)
            weight += occ[i]
    return total / max(weight, 1e-12)
@end
@16 n="heteronuclear_atomic_transfer_cost" d="Soft heteronuclear-contact mean of the lower free-atom electron-transfer cost minus the unit-charge Coulomb attraction, in eV." B=1237
def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    props = s.get('element_properties') or {}
    n = len(sites)
    occ = [max(0.0, x.get('occupancy', 1.0) or 0.0) for x in sites]
    radii = [max(0.1, (props.get(x.get('element')) or {}).get('covalent_radius_A') or 1.3) for x in sites]
    ion = [(props.get(x.get('element')) or {}).get('first_ionization_energy_eV') for x in sites]
    affinity = [(props.get(x.get('element')) or {}).get('electron_affinity_eV') for x in sites]
    total = 0.0
    weight = 0.0
    for b in s.get('neighbors') or []:
        i = b.get('i', -1)
        j = b.get('j', -1)
        d = b.get('distance_A') or 0.0
        if not (0 <= i < n and 0 <= j < n and 0.0 < d < 6.0):
            continue
        if sites[i].get('element') == sites[j].get('element'):
            continue
        if ion[i] is None or ion[j] is None or affinity[i] is None or affinity[j] is None:
            continue
        u = d / (1.5 * (radii[i] + radii[j]))
        w = occ[i] * occ[j] * max(0.0, 1.0 - u * u) ** 2
        cost = min(ion[i] - affinity[j], ion[j] - affinity[i]) - 14.399645478 / max(d, 0.1)
        total += w * cost
        weight += w
    return total / max(weight, 1e-12)
@end
@17 n="homonuclear_short_bond_excess" d="Excess short homonuclear bond-order proxy per occupied atom for electronegative group-14–17 sites; directed contacts are halved." B=1090
def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    props = s.get('element_properties') or {}
    n = len(sites)
    radii = [max(0.1, (props.get(x.get('element')) or {}).get('covalent_radius_A') or 1.3) for x in sites]
    occ = [max(0.0, x.get('occupancy', 1.0) or 0.0) for x in sites]
    total = 0.0
    for b in s.get('neighbors') or []:
        i = b.get('i', -1)
        j = b.get('j', -1)
        d = b.get('distance_A') or 0.0
        if not (0 <= i < n and 0 <= j < n and 0.0 < d <= 6.0):
            continue
        if occ[i] * occ[j] <= 0.0 or sites[i].get('element') != sites[j].get('element'):
            continue
        p = props.get(sites[i].get('element')) or {}
        group = p.get('group')
        en = p.get('eneg')
        if group is None or en is None or not (14 <= group <= 17) or en < 2.0:
            continue
        ratio = (radii[i] + radii[j]) / d
        if ratio > 1.0:
            order = min(3.0, min(2.0, ratio) ** 6)
            total += occ[i] * occ[j] * (order - 1.0)
    return 0.5 * total / max(sum(occ), 1e-12)
@end
@18 n="covalent_corrected_electron_balance" d="Signed main-group electron surplus per atom after radius-derived covalent bonds reduce the octet demand of electronegative group-14–17 sites." B=1863
def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    bonds = s.get('neighbors') or []
    props = s.get('element_properties') or {}
    n = len(sites)
    radii = [max(0.1, (props.get(x.get('element')) or {}).get('covalent_radius_A') or 1.3) for x in sites]
    occ = [max(0.0, x.get('occupancy', 1.0) or 0.0) for x in sites]
    total = 0.0
    for i in range(n):
        if occ[i] <= 0.0:
            continue
        p = props.get(sites[i].get('element')) or {}
        group = p.get('group')
        en = p.get('eneg')
        if group is None or en is None:
            continue
        if en < 2.0:
            if group == 1 or group == 2:
                total += occ[i] * group
            elif group == 13 or group == 14:
                total += occ[i] * (group - 10)
            continue
        if not (14 <= group <= 17):
            continue
        bond_sum = 0.0
        for b in bonds:
            if b.get('i', -1) != i:
                continue
            j = b.get('j', -1)
            d = b.get('distance_A') or 0.0
            if not (0 <= j < n and 0.0 < d <= 6.0) or occ[j] <= 0.0:
                continue
            q = props.get(sites[j].get('element')) or {}
            other_group = q.get('group')
            other_en = q.get('eneg')
            if other_group is None or other_en is None or other_en < 2.0:
                continue
            main_group = 14 <= other_group <= 17
            hydrogen = other_group == 1 and q.get('row') == 1
            if not (main_group or hydrogen):
                continue
            radius_sum = radii[i] + radii[j]
            if d <= 1.3 * radius_sum:
                ratio = min(2.0, radius_sum / d)
                bond_sum += occ[j] * min(3.0, ratio ** 6)
        total += occ[i] * (bond_sum - (18.0 - group))
    return total / max(sum(occ), 1e-12)
@end
@19 n="valence_electron_density" d="Composition-averaged H3 valence-electron count divided by atomic volume, in electrons per cubic angstrom." B=877
def feature(s):
    if not s:
        return 0.0
    props = s.get('element_properties') or {}
    total = 0.0
    weight = 0.0
    for element, fraction in (s.get('composition') or {}).items():
        if fraction is None or fraction <= 0.0:
            continue
        valence = (props.get(element) or {}).get('valence_electrons')
        if valence is None or valence < 0.0:
            continue
        total += fraction * valence
        weight += fraction
    volume = s.get('volume_per_atom_A3') or 0.0
    if volume <= 0.0:
        count = sum(max(0.0, x.get('occupancy', 1.0) or 0.0) for x in s.get('sites') or [])
        cell_volume = (s.get('lattice') or {}).get('volume_A3') or 0.0
        if count > 0.0 and cell_volume > 0.0:
            volume = cell_volume / count
    if volume <= 0.0 or weight <= 0.0:
        return 0.0
    return total / (weight * volume)
@end
